# N=4 Analysis Verification for M=2
def is_kawaii(sequence):
    N = len(sequence)

    if not sequence:
        return False

    M = max(sequence)

    # 1. Check if all numbers up to M are present
    present = set(sequence)
    for k in range(1, M + 1):
        if k not in present:
            return False

    # 2. Check ordering constraints for k >= 2
    for k in range(2, M + 1):

        indices_k = [i for i, x in enumerate(sequence) if x == k]
        indices_k_minus_1 = [i for i, x in enumerate(sequence) if x == k - 1]

        if not indices_k:
            continue

        i_first_k_minus_1 = min(indices_k_minus_1)
        j_last_k = max(indices_k)

        if i_first_k_minus_1 >= j_last_k:
            return False

    return True

count_n4_m2 = 0
for i in range(2**4):
    # Iterate over all 16 sequences made of {0, 1}. Map 0->1, 1->2.
    sequence_list = []
    for j in range(4):
        val = (i >> j) & 1
        sequence_list.append(val + 1)

    # Ensure we don't count sequences that are uniform (only 1s or only 2s)
    if all(x == 1 for x in sequence_list) or all(x == 2 for x in sequence_list):
        continue

    seq = tuple(sequence_list)
    if is_kawaii(seq):
        count_n4_m2 += 1

print(f"Count for N=4, M=2: {count_n4_m2}")
